import React, { useEffect, useState, useMemo } from 'react';
import { Filter, SlidersHorizontal, Package, RefreshCw } from 'lucide-react';
import { getProducts, getCategories, getBrands, type Product, type Category, type Brand } from '@/lib/services/store-data';
import { ProductCard } from '@/components/storefront/ProductCard';
import { useRouter } from '@/router';
import { useTranslation } from '@/i18n';

export function ShopView() {
  const { t, language } = useTranslation();
  const { searchParams } = useRouter();
  const [products, setProducts] = useState<Product[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [brands, setBrands] = useState<Brand[]>([]);
  const [loading, setLoading] = useState(true);

  // Filters state
  const [selectedBrand, setSelectedBrand] = useState<string>(searchParams.get('brand') || 'all');
  const [selectedCategory, setSelectedCategory] = useState<string>(searchParams.get('category') || 'all');
  const [selectedSize, setSelectedSize] = useState<string>(searchParams.get('size') || 'all');
  const [inStockOnly, setInStockOnly] = useState<boolean>(false);
  const [sortBy, setSortBy] = useState<'price_asc' | 'price_desc' | 'newest'>('newest');
  const searchQuery = searchParams.get('q') || '';

  useEffect(() => {
    Promise.all([
      getProducts({ publishedOnly: true }),
      getCategories(),
      getBrands(),
    ]).then(([p, c, b]) => {
      setProducts(p);
      setCategories(c);
      setBrands(b);
      setLoading(false);
    });
  }, []);

  const filteredProducts = useMemo(() => {
    let result = [...products];

    // Search query filter
    if (searchQuery.trim()) {
      const q = searchQuery.toLowerCase().trim();
      result = result.filter(
        (p) =>
          p.name.toLowerCase().includes(q) ||
          p.brand.toLowerCase().includes(q) ||
          p.variants.some((v) => v.size.toLowerCase() === q || v.sku.toLowerCase().includes(q))
      );
    }

    // Brand filter
    if (selectedBrand !== 'all') {
      result = result.filter((p) => p.brandSlug === selectedBrand);
    }

    // Category filter
    if (selectedCategory !== 'all') {
      result = result.filter((p) => p.categorySlug === selectedCategory);
    }

    // Size filter
    if (selectedSize !== 'all') {
      result = result.filter((p) => p.variants.some((v) => v.size === selectedSize));
    }

    // In-stock only filter
    if (inStockOnly) {
      result = result.filter((p) => p.variants.some((v) => v.stockQuantity > 0 && v.isAvailable));
    }

    // Sorting
    if (sortBy === 'price_asc') {
      result.sort((a, b) => a.basePrice - b.basePrice);
    } else if (sortBy === 'price_desc') {
      result.sort((a, b) => b.basePrice - a.basePrice);
    } else {
      // Newest
      result.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
    }

    return result;
  }, [products, searchQuery, selectedBrand, selectedCategory, selectedSize, inStockOnly, sortBy]);

  const resetFilters = () => {
    setSelectedBrand('all');
    setSelectedCategory('all');
    setSelectedSize('all');
    setInStockOnly(false);
    setSortBy('newest');
  };

  return (
    <div className="max-w-7xl mx-auto px-4 py-8 space-y-8">
      {/* Header Banner */}
      <div className="bg-gradient-to-r from-sky-600 to-sky-800 rounded-3xl p-6 sm:p-10 text-white shadow-md">
        <h1 className="text-2xl sm:text-4xl font-extrabold tracking-tight">
          {searchQuery ? `${language === 'bn' ? 'অনুসন্ধানের ফলাফল:' : 'Search Results for:'} "${searchQuery}"` : t.catalog.title}
        </h1>
        <p className="text-xs sm:text-sm text-sky-100 mt-2 max-w-xl">
          {t.catalog.subtitle}
        </p>
      </div>

      {/* Filter and Sort Toolbar */}
      <div className="bg-white rounded-2xl border border-slate-200/80 p-4 sm:p-6 shadow-xs space-y-4">
        <div className="flex flex-wrap items-center justify-between gap-4">
          <div className="flex items-center gap-2 text-slate-800 font-bold text-sm">
            <SlidersHorizontal className="w-4 h-4 text-sky-600" />
            <span>{language === 'bn' ? 'ফিল্টার এবং সাজান' : 'Filter & Sort'}</span>
            <span className="text-xs font-normal text-slate-500">
              ({filteredProducts.length} {language === 'bn' ? 'পণ্য উপলব্ধ' : 'products found'})
            </span>
          </div>

          <button
            onClick={resetFilters}
            className="text-xs font-semibold text-slate-500 hover:text-sky-600 flex items-center gap-1 transition-colors cursor-pointer"
          >
            <RefreshCw className="w-3.5 h-3.5" />
            <span>{t.catalog.resetFilters}</span>
          </button>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-3 pt-2 text-xs">
          {/* Brand select */}
          <div>
            <label className="block text-slate-500 font-semibold mb-1">{t.catalog.filterBrand}</label>
            <select
              value={selectedBrand}
              onChange={(e) => setSelectedBrand(e.target.value)}
              className="w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 text-xs font-medium text-slate-800 outline-hidden focus:border-sky-500 focus:bg-white"
            >
              <option value="all">{t.catalog.allBrands}</option>
              {brands.map((b) => (
                <option key={b.id} value={b.slug}>
                  {b.name}
                </option>
              ))}
            </select>
          </div>

          {/* Category select */}
          <div>
            <label className="block text-slate-500 font-semibold mb-1">{t.nav.categories}</label>
            <select
              value={selectedCategory}
              onChange={(e) => setSelectedCategory(e.target.value)}
              className="w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 text-xs font-medium text-slate-800 outline-hidden focus:border-sky-500 focus:bg-white"
            >
              <option value="all">{language === 'bn' ? 'সব ক্যাটাগরি' : 'All Categories'}</option>
              {categories.map((c) => (
                <option key={c.id} value={c.slug}>
                  {c.name}
                </option>
              ))}
            </select>
          </div>

          {/* Size select */}
          <div>
            <label className="block text-slate-500 font-semibold mb-1">{t.catalog.filterSize}</label>
            <select
              value={selectedSize}
              onChange={(e) => setSelectedSize(e.target.value)}
              className="w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 text-xs font-medium text-slate-800 outline-hidden focus:border-sky-500 focus:bg-white"
            >
              <option value="all">{t.catalog.allSizes}</option>
              <option value="S">Size S (4–8 kg)</option>
              <option value="M">Size M (6–11 kg)</option>
              <option value="L">Size L (9–14 kg)</option>
              <option value="XL">Size XL (12–17 kg)</option>
              <option value="XXL">Size XXL (15–25 kg)</option>
              <option value="XXXL">Size XXXL (18+ kg)</option>
            </select>
          </div>

          {/* Sort By */}
          <div>
            <label className="block text-slate-500 font-semibold mb-1">{t.catalog.sortBy}</label>
            <select
              value={sortBy}
              onChange={(e) => setSortBy(e.target.value as any)}
              className="w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 text-xs font-medium text-slate-800 outline-hidden focus:border-sky-500 focus:bg-white"
            >
              <option value="newest">{t.catalog.sortNewest}</option>
              <option value="price_asc">{t.catalog.sortPriceLow}</option>
              <option value="price_desc">{t.catalog.sortPriceHigh}</option>
            </select>
          </div>

          {/* Stock checkbox */}
          <div className="flex items-end pb-2">
            <label className="flex items-center gap-2 cursor-pointer text-xs font-semibold text-slate-700">
              <input
                type="checkbox"
                checked={inStockOnly}
                onChange={(e) => setInStockOnly(e.target.checked)}
                className="w-4 h-4 rounded-md text-sky-600 focus:ring-sky-500 border-slate-300"
              />
              <span>{t.catalog.filterInStock}</span>
            </label>
          </div>
        </div>
      </div>

      {/* Product Grid */}
      {filteredProducts.length === 0 ? (
        <div className="bg-white rounded-2xl border border-slate-200/80 p-12 text-center space-y-4">
          <div className="w-16 h-16 rounded-full bg-slate-100 flex items-center justify-center text-slate-400 mx-auto">
            <Package className="w-8 h-8" />
          </div>
          <p className="text-slate-700 font-bold text-base">{t.catalog.noProducts}</p>
          <button
            onClick={resetFilters}
            className="px-5 py-2.5 rounded-xl bg-sky-600 text-white font-semibold text-xs transition-colors hover:bg-sky-700 cursor-pointer"
          >
            {t.catalog.resetFilters}
          </button>
        </div>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6">
          {filteredProducts.map((p) => (
            <ProductCard key={p.id} product={p} />
          ))}
        </div>
      )}
    </div>
  );
}
